-- MoneyTree ledger backup 2026-09-12 02:00:03 PDT
-- Restore:
--   sqlite3 restored.sqlite3 < ledger.sql
--   cp restored.sqlite3 db.sqlite3
--   manage.py bootstrap_admin      # the login is not in this file
--   manage.py sync_bars --days 60  # nor are the bars
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_backtestrun" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "strategy_key" varchar(40) NOT NULL, "params" text NOT NULL CHECK ((JSON_VALID("params") OR "params" IS NULL)), "symbols" text NOT NULL CHECK ((JSON_VALID("symbols") OR "symbols" IS NULL)), "timeframe" varchar(8) NOT NULL, "start" date NOT NULL, "end" date NOT NULL, "starting_cash" decimal NOT NULL, "status" varchar(10) NOT NULL, "metrics" text NOT NULL CHECK ((JSON_VALID("metrics") OR "metrics" IS NULL)), "equity_curve" text NOT NULL CHECK ((JSON_VALID("equity_curve") OR "equity_curve" IS NULL)), "config_snapshot" text NOT NULL CHECK ((JSON_VALID("config_snapshot") OR "config_snapshot" IS NULL)), "window_label" varchar(40) NOT NULL, "tag" varchar(60) NOT NULL, "notes" text NOT NULL, "error" text NOT NULL, "created_at" datetime NOT NULL, "finished_at" datetime NULL, "duration_s" real NOT NULL, "experiment_id" bigint NULL REFERENCES "main_app_experiment" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "main_app_experiment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "strategy_key" varchar(40) NOT NULL, "method" varchar(16) NOT NULL, "param_grid" text NOT NULL CHECK ((JSON_VALID("param_grid") OR "param_grid" IS NULL)), "symbols" text NOT NULL CHECK ((JSON_VALID("symbols") OR "symbols" IS NULL)), "timeframe" varchar(8) NOT NULL, "start" date NOT NULL, "end" date NOT NULL, "objective" varchar(20) NOT NULL, "windows" text NOT NULL CHECK ((JSON_VALID("windows") OR "windows" IS NULL)), "min_trades" integer unsigned NOT NULL CHECK ("min_trades" >= 0), "status" varchar(10) NOT NULL, "progress" real NOT NULL, "total_runs" integer unsigned NOT NULL CHECK ("total_runs" >= 0), "done_runs" integer unsigned NOT NULL CHECK ("done_runs" >= 0), "best_params" text NOT NULL CHECK ((JSON_VALID("best_params") OR "best_params" IS NULL)), "summary" text NOT NULL CHECK ((JSON_VALID("summary") OR "summary" IS NULL)), "error" text NOT NULL, "pid" integer NOT NULL, "created_at" datetime NOT NULL, "finished_at" datetime NULL);
CREATE TABLE IF NOT EXISTS "main_app_marketsession" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL UNIQUE, "open_utc" datetime NOT NULL, "close_utc" datetime NOT NULL, "early_close" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_backtesttrade" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "symbol" varchar(16) NOT NULL, "side" varchar(5) NOT NULL, "qty" real NOT NULL, "entry_ts" datetime NOT NULL, "exit_ts" datetime NOT NULL, "entry_price" real NOT NULL, "exit_price" real NOT NULL, "pnl" real NOT NULL, "pnl_pct" real NOT NULL, "fees" real NOT NULL, "bars_held" integer unsigned NOT NULL CHECK ("bars_held" >= 0), "exit_reason" varchar(16) NOT NULL, "run_id" bigint NOT NULL REFERENCES "main_app_backtestrun" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "main_app_journalentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date" date NOT NULL, "kind" varchar(10) NOT NULL, "title" varchar(120) NOT NULL, "body" text NOT NULL, "metrics" text NOT NULL CHECK ((JSON_VALID("metrics") OR "metrics" IS NULL)), "proposals" text NOT NULL CHECK ((JSON_VALID("proposals") OR "proposals" IS NULL)), "created_at" datetime NOT NULL, "account_id" bigint NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "main_app_riskevent" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" datetime NOT NULL, "kind" varchar(32) NOT NULL, "message" varchar(300) NOT NULL, "data" text NOT NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "acknowledged_at" datetime NULL);
CREATE TABLE IF NOT EXISTS "main_app_equitysnapshot" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" datetime NOT NULL, "cash" decimal NOT NULL, "positions_value" decimal NOT NULL, "equity" decimal NOT NULL, "day_pnl" decimal NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" integer NOT NULL REFERENCES "account_emailaddress" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_signupinvite" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "email" varchar(254) NOT NULL UNIQUE, "note" varchar(120) NOT NULL, "make_operator" bool NOT NULL, "created_at" datetime NOT NULL, "used_at" datetime NULL, "invited_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "mfa_authenticator" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" varchar(20) NOT NULL, "data" text NOT NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "created_at" datetime NOT NULL, "last_used_at" datetime NULL);
CREATE TABLE IF NOT EXISTS "socialaccount_socialapp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "name" varchar(40) NOT NULL, "client_id" varchar(191) NOT NULL, "secret" varchar(191) NOT NULL, "key" varchar(191) NOT NULL, "provider_id" varchar(200) NOT NULL, "settings" text NOT NULL CHECK ((JSON_VALID("settings") OR "settings" IS NULL)));
CREATE TABLE IF NOT EXISTS "socialaccount_socialtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "token_secret" text NOT NULL, "expires_at" datetime NULL, "account_id" integer NOT NULL REFERENCES "socialaccount_socialaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "app_id" integer NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "socialaccount_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(200) NOT NULL, "uid" varchar(191) NOT NULL, "last_login" datetime NOT NULL, "date_joined" datetime NOT NULL, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "extra_data" text NOT NULL CHECK ((JSON_VALID("extra_data") OR "extra_data" IS NULL)));
CREATE TABLE IF NOT EXISTS "main_app_account" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "mode" varchar(8) NOT NULL, "name" varchar(40) NOT NULL, "starting_cash" decimal NOT NULL, "cash" decimal NOT NULL, "equity" decimal NOT NULL, "buying_power" decimal NOT NULL, "day_start_equity" decimal NOT NULL, "day_start_date" date NULL, "last_synced_at" datetime NULL, "created_at" datetime NOT NULL, "reset_at" datetime NULL, "market" varchar(8) NOT NULL, "day_entries" integer unsigned NOT NULL CHECK ("day_entries" >= 0), "day_halted" bool NOT NULL, "day_halted_reason" varchar(120) NOT NULL, "last_reconcile_at" datetime NULL, "reconcile_note" varchar(300) NOT NULL, "reconcile_ok" bool NOT NULL, CONSTRAINT "uniq_account_mode_market" UNIQUE ("mode", "market"));
CREATE TABLE IF NOT EXISTS "main_app_agentrun" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "mode" varchar(8) NOT NULL, "started_at" datetime NOT NULL, "last_tick_at" datetime NULL, "stopped_at" datetime NULL, "pid" integer NOT NULL, "status" varchar(10) NOT NULL, "message" varchar(300) NOT NULL, "ticks" integer unsigned NOT NULL CHECK ("ticks" >= 0), "replay_date" date NULL, "speed" real NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "market" varchar(8) NOT NULL, "data_source" varchar(24) NOT NULL, "expected_interval_s" integer unsigned NOT NULL CHECK ("expected_interval_s" >= 0), "last_bar_ts" datetime NULL, "next_action_at" datetime NULL, "state" varchar(12) NOT NULL, "stop_requested" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_feedevent" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" datetime NOT NULL, "level" varchar(8) NOT NULL, "symbol" varchar(16) NOT NULL, "strategy_key" varchar(40) NOT NULL, "data" text NOT NULL CHECK ((JSON_VALID("data") OR "data" IS NULL)), "account_id" bigint NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "bar_ts" datetime NULL, "phase" varchar(10) NOT NULL, "text" varchar(600) NOT NULL, "card_id" bigint NULL REFERENCES "main_app_tradecard" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "main_app_symbolstate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "symbol" varchar(16) NOT NULL, "ts" datetime NOT NULL, "bar_ts" datetime NULL, "price" real NOT NULL, "source" varchar(24) NOT NULL, "decision" varchar(12) NOT NULL, "summary" varchar(600) NOT NULL, "rules" text NOT NULL CHECK ((JSON_VALID("rules") OR "rules" IS NULL)), "proximity" real NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_symbol_state" UNIQUE ("account_id", "symbol"));
CREATE TABLE IF NOT EXISTS "main_app_fill" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" datetime NOT NULL, "qty" decimal NOT NULL, "fee" decimal NOT NULL, "realized_slippage_bps" real NULL, "order_id" bigint NOT NULL REFERENCES "main_app_order" ("id") DEFERRABLE INITIALLY DEFERRED, "price" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_instrument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "symbol" varchar(16) NOT NULL UNIQUE, "name" varchar(80) NOT NULL, "asset_class" varchar(8) NOT NULL, "qty_increment" decimal NOT NULL, "in_watchlist" bool NOT NULL, "active" bool NOT NULL, "created_at" datetime NOT NULL, "market" varchar(8) NOT NULL, "tick_size" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_order" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "strategy_key" varchar(40) NOT NULL, "side" varchar(4) NOT NULL, "qty" decimal NOT NULL, "order_type" varchar(8) NOT NULL, "limit_price" decimal NULL, "time_in_force" varchar(4) NOT NULL, "status" varchar(20) NOT NULL, "client_order_id" varchar(120) NOT NULL UNIQUE, "broker_order_id" varchar(80) NOT NULL, "leg" varchar(8) NOT NULL, "decision_price" decimal NULL, "bar_ts" datetime NULL, "reason" varchar(200) NOT NULL, "submitted_at" datetime NOT NULL, "filled_at" datetime NULL, "filled_qty" decimal NOT NULL, "filled_avg_price" decimal NULL, "fees" decimal NOT NULL, "error" text NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "instrument_id" bigint NOT NULL REFERENCES "main_app_instrument" ("id") DEFERRABLE INITIALLY DEFERRED, "stop_price" decimal NULL);
CREATE TABLE IF NOT EXISTS "main_app_position" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "strategy_key" varchar(40) NOT NULL, "qty" decimal NOT NULL, "avg_price" decimal NOT NULL, "stop_price" decimal NULL, "opened_at" datetime NOT NULL, "entry_bar_ts" datetime NULL, "bars_held" integer unsigned NOT NULL CHECK ("bars_held" >= 0), "max_hold_until" datetime NULL, "last_price" decimal NULL, "entry_fees" decimal NOT NULL, "external" bool NOT NULL, "updated_at" datetime NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "instrument_id" bigint NOT NULL REFERENCES "main_app_instrument" ("id") DEFERRABLE INITIALLY DEFERRED, "closing" bool NOT NULL, "protection" varchar(12) NOT NULL, "protection_order_id" varchar(80) NOT NULL, "target_price" decimal NULL, CONSTRAINT "uniq_position" UNIQUE ("account_id", "instrument_id"));
CREATE TABLE IF NOT EXISTS "main_app_signal" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "strategy_key" varchar(40) NOT NULL, "ts" datetime NOT NULL, "action" varchar(6) NOT NULL, "strength" real NOT NULL, "price" decimal NULL, "stop_price" decimal NULL, "reason" varchar(200) NOT NULL, "acted" bool NOT NULL, "blocked_reason" varchar(200) NOT NULL, "created_at" datetime NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "instrument_id" bigint NOT NULL REFERENCES "main_app_instrument" ("id") DEFERRABLE INITIALLY DEFERRED, "order_id" bigint NULL REFERENCES "main_app_order" ("id") DEFERRABLE INITIALLY DEFERRED, "target_price" decimal NULL);
CREATE TABLE IF NOT EXISTS "main_app_trade" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "strategy_key" varchar(40) NOT NULL, "side" varchar(5) NOT NULL, "qty" decimal NOT NULL, "entry_ts" datetime NOT NULL, "exit_ts" datetime NOT NULL, "entry_price" decimal NOT NULL, "pnl" decimal NOT NULL, "pnl_pct" decimal NOT NULL, "fees" decimal NOT NULL, "bars_held" integer unsigned NOT NULL CHECK ("bars_held" >= 0), "exit_reason" varchar(16) NOT NULL, "notes" varchar(200) NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "instrument_id" bigint NOT NULL REFERENCES "main_app_instrument" ("id") DEFERRABLE INITIALLY DEFERRED, "exit_price" decimal NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_tradecard" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "entry_order_id" varchar(120) NOT NULL UNIQUE, "symbol" varchar(16) NOT NULL, "strategy_key" varchar(40) NOT NULL, "side" varchar(5) NOT NULL, "status" varchar(20) NOT NULL, "bar_ts" datetime NULL, "decision_price" decimal NULL, "planned_entry" decimal NULL, "stop_price" decimal NULL, "qty" decimal NOT NULL, "risk_dollars" decimal NOT NULL, "reward_dollars" decimal NOT NULL, "expected_costs" decimal NOT NULL, "reward_risk" decimal NOT NULL, "reason" varchar(300) NOT NULL, "rules" text NOT NULL CHECK ((JSON_VALID("rules") OR "rules" IS NULL)), "broker_order_id" varchar(80) NOT NULL, "protection" varchar(12) NOT NULL, "protection_order_id" varchar(80) NOT NULL, "filled_qty" decimal NOT NULL, "avg_fill" decimal NULL, "fees" decimal NOT NULL, "slippage_bps" real NULL, "exit_reason" varchar(16) NOT NULL, "exit_price" decimal NULL, "gross_pnl" decimal NULL, "net_pnl" decimal NULL, "error" varchar(300) NOT NULL, "approval_expires_at" datetime NULL, "approved_by" varchar(80) NOT NULL, "opened_at" datetime NULL, "closed_at" datetime NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "account_id" bigint NOT NULL REFERENCES "main_app_account" ("id") DEFERRABLE INITIALLY DEFERRED, "target_price" decimal NULL);
CREATE TABLE IF NOT EXISTS "main_app_bar" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "timeframe" varchar(8) NOT NULL, "ts" datetime NOT NULL, "open" real NOT NULL, "high" real NOT NULL, "low" real NOT NULL, "close" real NOT NULL, "volume" real NOT NULL, "vwap" real NULL, "trade_count" integer NULL, "source" varchar(32) NOT NULL, "instrument_id" bigint NOT NULL REFERENCES "main_app_instrument" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uniq_bar" UNIQUE ("instrument_id", "timeframe", "source", "ts"));
CREATE TABLE IF NOT EXISTS "main_app_strategy" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "key" varchar(40) NOT NULL, "name" varchar(80) NOT NULL, "params" text NOT NULL CHECK ((JSON_VALID("params") OR "params" IS NULL)), "enabled" bool NOT NULL, "symbols" text NOT NULL CHECK ((JSON_VALID("symbols") OR "symbols" IS NULL)), "timeframe" varchar(8) NOT NULL, "allocation_pct" decimal NOT NULL, "stage" varchar(8) NOT NULL, "version" integer unsigned NOT NULL CHECK ("version" >= 0), "history" text NOT NULL CHECK ((JSON_VALID("history") OR "history" IS NULL)), "notes" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "market" varchar(8) NOT NULL, "qualification" varchar(12) NOT NULL, "qualification_reason" varchar(300) NOT NULL, "qualification_updated_at" datetime NULL, "evidence_since" datetime NULL, CONSTRAINT "uniq_strategy_key_market" UNIQUE ("key", "market"));
CREATE TABLE IF NOT EXISTS "main_app_apiusage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ts" datetime NOT NULL, "model" varchar(60) NOT NULL, "purpose" varchar(40) NOT NULL, "input_tokens" integer unsigned NOT NULL CHECK ("input_tokens" >= 0), "output_tokens" integer unsigned NOT NULL CHECK ("output_tokens" >= 0), "cost_usd" decimal NOT NULL, "cached_tokens" integer unsigned NOT NULL CHECK ("cached_tokens" >= 0), "calls" integer unsigned NOT NULL CHECK ("calls" >= 0), "note" varchar(200) NOT NULL, "project" varchar(30) NOT NULL, "provider" varchar(20) NOT NULL);
CREATE TABLE IF NOT EXISTS "main_app_newsitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "external_id" varchar(64) NOT NULL UNIQUE, "source" varchar(40) NOT NULL, "published_at" datetime NOT NULL, "headline" varchar(500) NOT NULL, "summary" text NOT NULL, "url" varchar(500) NOT NULL, "symbols" text NOT NULL CHECK ((JSON_VALID("symbols") OR "symbols" IS NULL)), "market" varchar(8) NOT NULL, "classified_at" datetime NULL, "kind" varchar(16) NOT NULL, "direction" varchar(8) NOT NULL, "magnitude" smallint unsigned NOT NULL CHECK ("magnitude" >= 0), "confidence" smallint unsigned NOT NULL CHECK ("confidence" >= 0), "horizon" varchar(12) NOT NULL, "novel" bool NOT NULL, "rationale" varchar(400) NOT NULL, "tradable" bool NOT NULL, "model" varchar(60) NOT NULL, "price_at_news" text NOT NULL CHECK ((JSON_VALID("price_at_news") OR "price_at_news" IS NULL)), "outcome" text NOT NULL CHECK ((JSON_VALID("outcome") OR "outcome" IS NULL)), "outcome_at" datetime NULL, "created_at" datetime NOT NULL, "duplicate_of_id" bigint NULL REFERENCES "main_app_newsitem" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "main_app_agentconfig" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "mode" varchar(8) NOT NULL, "trading_enabled" bool NOT NULL, "kill_switch" bool NOT NULL, "timeframe" varchar(8) NOT NULL, "starting_cash" decimal NOT NULL, "risk_per_trade_pct" decimal NOT NULL, "max_position_pct" decimal NOT NULL, "max_open_positions" integer unsigned NOT NULL CHECK ("max_open_positions" >= 0), "max_daily_loss_pct" decimal NOT NULL, "max_trades_per_day" integer unsigned NOT NULL CHECK ("max_trades_per_day" >= 0), "no_entries_before_close_min" integer unsigned NOT NULL CHECK ("no_entries_before_close_min" >= 0), "flat_before_close_min" integer unsigned NOT NULL CHECK ("flat_before_close_min" >= 0), "allow_short" bool NOT NULL, "max_hold_minutes" integer unsigned NOT NULL CHECK ("max_hold_minutes" >= 0), "slippage_bps" decimal NOT NULL, "fee_bps_stock" decimal NOT NULL, "fee_bps_crypto" decimal NOT NULL, "liquidity_cap_pct" decimal NOT NULL, "live_armed_at" datetime NULL, "live_confirm_orders" bool NOT NULL, "live_sessions_completed" integer unsigned NOT NULL CHECK ("live_sessions_completed" >= 0), "updated_at" datetime NOT NULL, "crypto_timeframe" varchar(8) NOT NULL, "min_reward_to_cost" decimal NOT NULL, "live_confirm_minutes" integer unsigned NOT NULL CHECK ("live_confirm_minutes" >= 0), "degen_max_daily_loss_pct" decimal NOT NULL, "degen_max_hold_minutes" integer unsigned NOT NULL CHECK ("degen_max_hold_minutes" >= 0), "degen_max_open_positions" integer unsigned NOT NULL CHECK ("degen_max_open_positions" >= 0), "degen_max_position_pct" decimal NOT NULL, "degen_max_trades_per_day" integer unsigned NOT NULL CHECK ("degen_max_trades_per_day" >= 0), "degen_min_reward_to_cost" decimal NOT NULL, "degen_risk_per_trade_pct" decimal NOT NULL, "degen_timeframe" varchar(8) NOT NULL, "pulse_seconds" integer unsigned NOT NULL CHECK ("pulse_seconds" >= 0), "fee_bps_forex" decimal NOT NULL, "forex_leverage" decimal NOT NULL, "forex_max_daily_loss_pct" decimal NOT NULL, "forex_max_hold_minutes" integer unsigned NOT NULL CHECK ("forex_max_hold_minutes" >= 0), "forex_max_open_positions" integer unsigned NOT NULL CHECK ("forex_max_open_positions" >= 0), "forex_max_position_pct" decimal NOT NULL, "forex_max_trades_per_day" integer unsigned NOT NULL CHECK ("forex_max_trades_per_day" >= 0), "forex_min_reward_to_cost" decimal NOT NULL, "forex_risk_per_trade_pct" decimal NOT NULL, "forex_slippage_bps" decimal NOT NULL, "forex_timeframe" varchar(8) NOT NULL, "forex_max_directional_exposure_pct" decimal NOT NULL, "degen_max_directional_exposure_pct" decimal NOT NULL, "news_enabled" bool NOT NULL);
